import numpy as np
from PIL import Image
import colorsys, glob

im = np.asarray(Image.open('barcode.png').convert('RGB')).astype(float)/255.0
cm = im.mean(axis=0)  # 1000x3

def hsv_profile(rgb):
    out=[]
    for r,g,b in rgb:
        h,s,v = colorsys.rgb_to_hsv(max(r,0),max(g,0),max(b,0))
        out.append((h,s,v))
    return np.array(out)

# Downsample barcode to 200 bins for speed
idx = np.linspace(0,1000,201).astype(int)
T = hsv_profile(np.array([cm[idx[i]:max(idx[i+1],idx[i]+1)].mean(axis=0) for i in range(200)]))

def film_profile(folder):
    files = sorted(glob.glob(folder+'/*.jpg'))
    prof=[]
    for f in files:
        a = np.asarray(Image.open(f).convert('RGB')).astype(float)/255.0
        prof.append(a.mean(axis=(0,1)))
    return hsv_profile(np.array(prof))

def dtw_cost(A, B, weights=(1,1,1)):
    n,m = len(A), len(B)
    D = np.full((n+1,m+1), 1e9); D[0,0]=0
    w = np.array(weights)
    for i in range(1,n+1):
        for j in range(1,m+1):
            cost = (np.abs(A[i-1]-B[j-1])*w).sum()
            D[i,j] = cost + min(D[i-1,j], D[i,j-1], D[i-1,j-1])
    return D[n,m]/(n+m)

T2 = T.copy()
# hue circular handling: use sin/cos encoding
def enc(P):
    return np.stack([np.cos(2*np.pi*P[:,0]), np.sin(2*np.pi*P[:,0]), P[:,1], P[:,2]], axis=1)
TE = enc(T2)

for folder,label in [('illu','Illusionist'), ('ramp','Rampart')]:
    P = film_profile(folder)
    PE = enc(P)
    # resample film profile to 200 via linear interp
    xs = np.linspace(0, len(P)-1, 200)
    PI = np.stack([np.interp(xs, np.arange(len(P)), PE[:,k]) for k in range(4)], axis=1)
    c = dtw_cost(TE, PE)
    print(f"{label}: DTW hue-sat-val cost = {c:.3f}")
EOF"}

